// This may look like C code, but it is really -*- C++ -*-// A Bison++ parser, made from ParseExpr.y #ifndef PARSEEXPR_Y #define PARSEEXPR_Y typedef union {	int ival;	char* sval;	Fields fval;	CardType tval;	Tree* trval;	Node* nval;} ParseExpr_YYSTYPE;typedef  struct ParseExpr_YYLTYPE {   int timestamp;   int first_line;   int first_column;   int last_line;   int last_column;   char *text;};class ParseExpr {private:   int yychar;   ParseExpr_YYSTYPE yylval;   ParseExpr_YYLTYPE yylloc;   int yynerrs;protected:public:  ParseExpr() {};  int yyparse();  void yyerror(char *);  int yylex();  static const int	INTEGER;  static const int	STRING;  static const int	FIELD;  static const int	CARDTYPE;  static const int	BADWORD;  static const int	NOTEQ;  static const int	LESSEQ;  static const int	GREATEREQ;};#endif PARSEEXPR_Y